mapper.insert:
INSERT INTO stat.map_building (district_code, building_id, height, under_construction, geom) SELECT v.code, v.building_id, v.height, v.uc, ST_Multi(ST_CollectionExtract(ST_MakeValid(ST_Transform(ST_GeomFromEWKB(decode(v.hex, 'hex')), 3857)), 3)) FROM (VALUES
(#{b.code}, #{b.buildingId}, #{b.height}::numeric, #{b.underConstruction}::boolean, #{b.ewkbHex})
) AS v(code, building_id, height, uc, hex)
